#include <stdio.h>

// Prototype (déclaration)
int maximum(int a, int b);
void afficher_carre(int n);

int main() {
    printf("Max : %d\n", maximum(7, 3));
    afficher_carre(4);
    return 0;
}

// Définitions
int maximum(int a, int b) {
    return (a > b) ? a : b;
}

void afficher_carre(int n) {
    printf("%d x %d = %d\n", n, n, n * n);
}
